// Root certificates trusted for HTTPS (DER). ca_roots.c is generated by
// tools/gen_ca_roots.py from Mozilla's CA store.

#ifndef DSHA_CA_ROOTS_H
#define DSHA_CA_ROOTS_H

#include <stddef.h>

typedef struct {
    const unsigned char *der;
    size_t len;
} ca_root;

extern const ca_root ca_roots[];
extern const int ca_roots_count;

#endif // DSHA_CA_ROOTS_H
